import sys
from enum import Enum

class Mst(object):
	INFINITY = 999999999

	class Status(Enum):
		white = 1
		gray = 2
		black = 3

	def __init__(self, nodes, data):
		self.num_of_pathes = len(data)
		self.color = [Mst.Status.white] * nodes
		self.M = self._make_matrix(nodes, data)
		self.d = [Mst.INFINITY] * nodes
		self.p = [-1] * nodes

	def _make_matrix(self, nodes, data):
		m = [[Mst.INFINITY] * nodes for _ in range(nodes)]
		for d in data:
			m[d[0]][d[1]] = d[2]
			m[d[1]][d[0]] = d[2]
		return m

	def prim(self):
		self.d[0] = 0
		self.p[0] = -1
		while True:
			mincost = Mst.INFINITY
			for i in range(len(self.d)):
				if self.color[i] != Mst.Status.black and self.d[i] < mincost:
					mincost = self.d[i]
					u = i
			if mincost == Mst.INFINITY:
				break
			self.color[u] = Mst.Status.black
			for v in range(len(self.d)):
				if self.color[v] != Mst.Status.black and self.M[u][v] != Mst.INFINITY:
					if self.M[u][v] < self.d[v]:
						self.d[v] = self.M[u][v]
						self.p[v] = u
						self.color[v] = Mst.Status.gray
		results = []
		for i in range(len(self.p)):
			if self.p[i] != -1:
				results.append(self.M[i][self.p[i]] / 100 - 1)
		return int(sum(results))

def main(args):
	while True:
		n = int(input())
		if n == 0:
			break
		m = int(input())
		pathes = []
		for _ in range(m):
			pathes.append([int(x) for x in input().split(',')])
		s = Mst(n, pathes)
		result = s.prim()
		print(result)
main(sys.argv[1:])

